starterFiles.content:
body { margin: 0; font-family: system-ui, sans-serif; }
.nav { display: flex; gap: 1rem; align-items: center; padding: 1rem; background: #1e293b; }
.nav a, .dropdown-toggle { color: white; background: none; border: 0; font: inherit; cursor: pointer; }

.dropdown-menu {
  position: absolute;
  top: 100%;
  left: 0;
  display: none;
  margin: 0;
  padding: 0.5rem 0;
  list-style: none;
  background: white;
  min-width: 160px;
}
.dropdown-menu a { display: block; padding: 0.5rem 1rem; color: #1e293b; }
.dropdown:hover .dropdown-menu { display: block }
.dropdown-menu:hover { display: none; }

.hero {
  position: relative;
  z-index: 10;
  min-height: 60vh;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, #0ea5e9, #6366f1);
  color: white;
}

.dropdown-toggle:hover { transition: color 0.3s; color: #fbbf24; }
